/**
 * The recipe card through the compiled core, records as JavaScript objects (jvm/web/README.md, "Records across the
 * boundary"): the website's `CardInputCase` object goes in as it is, `ViewExports.viewCardJs` reads it field by field
 * and builds the `CardView` and `CardGeometry` objects (Java `ViewJs`, generated by tools/web-core/gen-wire.mjs from
 * the records). No JSON text on either side. The objects equal `JSON.parse` of the JSON export's answer
 * (`viewCardMeasured`), key order included; card-shadow.test.ts holds this path to the website's own card.
 */
import type { CoreExports } from "./exports.generated";
import type { CardGeometry, CardInputCase, CardView } from "./records.generated";

/** The host's text widths by `TextStyle` name, in board px (the core calls it back for each width it needs). */
export interface CardMeasure {
  width(style: string, text: string): number;
}

/**
 * A card's view and geometry from its input; widths from `measure`, or six px a character when it is left out. With a
 * `fontState` the core keeps the widths it asked while the state stays the same (`viewCardJsKept`): the measure must
 * give one width per (style, text) for one state.
 */
export function cardThroughCore(
  view: CoreExports["ViewExports"],
  input: CardInputCase,
  measure?: CardMeasure,
  fontState?: number,
): { view: CardView; geometry: CardGeometry } {
  const out = !measure
    ? view.viewCardJsSix(input)
    : fontState !== undefined
      ? view.viewCardJsKept(input, measure as unknown as Record<string, unknown>, fontState)
      : view.viewCardJs(input, measure as unknown as Record<string, unknown>);
  return out as { view: CardView; geometry: CardGeometry };
}
